parameters.jsCode:
const row = $input.first().json || {};

const raw = {
  email: String(row.email || '').trim().toLowerCase(),
  name: String(row.name || '').trim(),
  company: String(row.company || '').trim(),
  role: String(row.role || '').trim(),
  source: String(row.source || '').trim(),
  row_number: row.row_number
};

if (!raw.email || !raw.email.includes('@')) {
  // Surface a structured skip instead of throwing — downstream IF could drop these,
  // but for the template we let the model see a sparse record and score it low.
  return [{ json: { ...raw, _validation: 'missing_or_invalid_email', _ok: false } }];
}

if (!raw.company) {
  // Best-effort: derive company guess from email domain (skip free webmail).
  const domain = raw.email.split('@')[1] || '';
  const free = ['gmail.com','outlook.com','yahoo.com','hotmail.com','icloud.com','proton.me','protonmail.com'];
  if (domain && !free.includes(domain)) {
    raw.company = domain.replace(/\.[a-z.]+$/, '').replace(/[-_]/g,' ');
    raw._company_inferred_from = domain;
  }
}

return [{ json: { ...raw, _ok: true } }];

const c = $input.first().json;

const systemPrompt = `You are a B2B sales-research analyst. Given a contact record (name + email + company + optional role + source), you produce a structured enrichment record using only your general knowledge — do not fabricate specific facts that you don't have high confidence in.

Return ONLY a single JSON object, no prose, no code fences. Shape:
{
  "company": {
    "name": "<canonical company name or best inference, empty string if unknown>",
    "industry": "<one of: SaaS|Ecommerce|Marketing|Finance|Healthcare|Education|Manufacturing|Construction|Hospitality|RealEstate|Legal|Logistics|NotForProfit|Other|Unknown>",
    "size_band": "<one of: solo|2-10|11-50|51-200|201-1000|1000+|unknown>",
    "hq_country": "<ISO country code or empty>",
    "business_model": "<one of: B2B|B2C|B2B2C|Marketplace|Unknown>",
    "signals": ["<short signal 1>", "<short signal 2>", "<short signal 3>"]
  },
  "contact": {
    "role_seniority": "<one of: ic|senior_ic|manager|director|vp|c_level|founder|unknown>",
    "role_function": "<one of: engineering|product|marketing|sales|ops|finance|hr|exec|other|unknown>"
  },
  "outreach": {
    "hook": "<one short sentence — a plausible, specific outreach angle>",
    "confidence": "<low|medium|high>"
  },
  "confidence_notes": "<one sentence on what you're confident vs guessing about>"
}

Rules:
- If you genuinely don't know a field, use "unknown" / empty string / empty array — never invent.
- Signals are short factual phrases ("public SaaS company", "YC-backed", "AU-based marketplace") — not invented news.
- The hook should be plausible and specific to the inferred profile, not generic ("hope you're well" is a fail).`;

const userPrompt = `Contact record:\n- name: ${c.name || '(unknown)'}\n- email: ${c.email}\n- company: ${c.company || '(unknown)'}\n- role: ${c.role || '(unknown)'}\n- source: ${c.source || '(unknown)'}\n\nEnrich + return JSON only.`;

const fullPrompt = `${systemPrompt}\n\n---\n\n${userPrompt}`;

return [{ json: { ...c, _gemini_prompt: fullPrompt } }];

const gemini = $input.first().json;
const raw = gemini?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

let enrichment;
try {
  enrichment = JSON.parse(raw);
} catch (e) {
  enrichment = {
    company: { name: '', industry: 'Unknown', size_band: 'unknown', hq_country: '', business_model: 'Unknown', signals: [] },
    contact: { role_seniority: 'unknown', role_function: 'unknown' },
    outreach: { hook: '', confidence: 'low' },
    confidence_notes: 'Model returned non-JSON; defaults applied.'
  };
}

// Defensive defaults so downstream ICP scorer never NPEs.
enrichment.company = enrichment.company || {};
enrichment.contact = enrichment.contact || {};
enrichment.outreach = enrichment.outreach || {};
enrichment.company.signals = Array.isArray(enrichment.company.signals) ? enrichment.company.signals : [];

const prev = $('Build Gemini Enrichment Prompt').item.json;

return [{ json: {
  email: prev.email,
  name: prev.name,
  company_input: prev.company,
  role_input: prev.role,
  source: prev.source,
  row_number: prev.row_number,
  enrichment
} }];

const icpRow = $input.first().json;
const icps = (icpRow && icpRow.icps) || [];
const prev = $('Parse Gemini Output').item.json;
const e = prev.enrichment;

// 4-axis match: industry / size_band / role_seniority / business_model.
// Each axis worth 25 points. ICP-level weight scales the final score.
function matchAxis(arr, val) {
  if (!Array.isArray(arr) || arr.length === 0) return true;   // unconstrained = match
  if (!val || val === 'unknown' || val === 'Unknown') return false;
  return arr.includes(val);
}

let best = { icp_id: null, icp_name: 'no-icp-match', score: 0 };
for (const icp of icps) {
  const axes = [
    matchAxis(icp.target_industries, e.company.industry),
    matchAxis(icp.target_size_bands, e.company.size_band),
    matchAxis(icp.target_role_seniorities, e.contact.role_seniority),
    matchAxis(icp.target_business_models, e.company.business_model)
  ];
  const hits = axes.filter(Boolean).length;
  const base = hits * 25;
  const weighted = Math.round(base * (Number(icp.weight) || 1.0));
  const score = Math.min(100, weighted);
  if (score > best.score) best = { icp_id: icp.id, icp_name: icp.name, score };
}

// Band thresholds. Tune in the icp_profiles seed comment if you re-baseline.
let band;
if (best.score >= 75) band = 'hot';
else if (best.score >= 40) band = 'warm';
else band = 'cold';

return [{ json: { ...prev, icp_match: best, score: best.score, band } }];

