Company: ${$('Score Against ICPs').item.json.enrichment.company.name || '(unknown)'} — ${$('Score Against ICPs').item.json.enrichment.company.industry} / ${$('Score Against ICPs').item.json.enrichment.company.size_band}
Role: ${$('Score Against ICPs').item.json.enrichment.contact.role_seniority} / ${$('Score Against ICPs').item.json.enrichment.contact.role_function}
Hook: ${$('Score Against ICPs').item.json.enrichment.outreach.hook || '(none drafted)'}` }) }}
